#define WAKE_COMMAND         0x400   /* command landed (sticky) */
#define WAKE_RUN_DONE        0x800   /* engine run done: rd_done rose (sticky) */
#define WAKE_REQUEST_ROOM    0x1000   /* request FIFO no longer full (sticky) */
